/** Return one JSON value for one Type. */
export function toJsonType(value: Type): Json {
    switch (value.kind) {
        case "error":
            return {
                kind: "error",
            };
        case "never":
            return {
                kind: "never",
            };
        case "void":
            return {
                kind: "void",
            };
        case "boolean":
            return {
                kind: "boolean",
            };
        case "character":
            return {
                kind: "character",
            };
        case "int":
            return {
                kind: "int",
                width: value.width,
                isSigned: value.isSigned,
            };
        case "isize":
            return {
                kind: "isize",
            };
        case "usize":
            return {
                kind: "usize",
            };
        case "float":
            return {
                kind: "float",
                float: toJsonFloatType(value.float),
            };
        case "typeDescriptor":
            return {
                kind: "typeDescriptor",
            };
        case "typeId":
            return {
                kind: "typeId",
            };
        case "atomic":
            return {
                kind: "atomic",
                value: toJsonLocalNodeId(value.value),
            };
        case "dynamic":
            return {
                kind: "dynamic",
                kindValue: toJsonReferenceKind(value.kindValue),
                lifetime: toJsonLifetime(value.lifetime),
                constraint: toJsonLocalNodeId(value.constraint),
                storage: toJsonStorage(value.storage),
                access: toJsonAccess(value.access),
                nullability: toJsonNullability(value.nullability),
            };
        case "reference":
            return {
                kind: "reference",
                kindValue: toJsonReferenceKind(value.kindValue),
                lifetime: toJsonLifetime(value.lifetime),
                storage: toJsonStorage(value.storage),
                access: toJsonAccess(value.access),
                pointee: toJsonLocalNodeId(value.pointee),
                nullability: toJsonNullability(value.nullability),
            };
        case "pointer":
            return {
                kind: "pointer",
                pointee: toJsonLocalNodeId(value.pointee),
                access: toJsonAccess(value.access),
                nullability: toJsonNullability(value.nullability),
            };
        case "slice":
            return {
                kind: "slice",
                kindValue: toJsonReferenceKind(value.kindValue),
                lifetime: toJsonLifetime(value.lifetime),
                element: toJsonLocalNodeId(value.element),
                storage: toJsonStorage(value.storage),
                access: toJsonAccess(value.access),
                nullability: toJsonNullability(value.nullability),
            };
        case "uninit":
            return {
                kind: "uninit",
                value: toJsonLocalNodeId(value.value),
            };
        case "manuallyDrop":
            return {
                kind: "manuallyDrop",
                value: toJsonLocalNodeId(value.value),
            };
        case "fixedArray":
            return {
                kind: "fixedArray",
                element: toJsonLocalNodeId(value.element),
                length: value.length.toString(),
                copy: toJsonCopy(value.copy),
            };
        case "tuple":
            return {
                kind: "tuple",
                elements: value.elements.map((item0) => toJsonLocalNodeId(item0)),
                copy: toJsonCopy(value.copy),
            };
        case "struct":
            return {
                kind: "struct",
                fields: value.fields.map((item0) => toJsonLocalNodeId(item0)),
                copy: toJsonCopy(value.copy),
            };
        case "newtype":
            return {
                kind: "newtype",
                inner: toJsonLocalNodeId(value.inner),
                copy: toJsonCopy(value.copy),
            };
        case "variant":
            return {
                kind: "variant",
                discriminant: toJsonLocalNodeId(value.discriminant),
                cases: value.cases.map((item0) => toJsonVariantCase(item0)),
                copy: toJsonCopy(value.copy),
            };
        case "vector":
            return {
                kind: "vector",
                element: toJsonLocalNodeId(value.element),
                lanes: value.lanes,
                copy: toJsonCopy(value.copy),
            };
        case "tensor":
            return {
                kind: "tensor",
                kindValue: toJsonReferenceKind(value.kindValue),
                lifetime: toJsonLifetime(value.lifetime),
                storage: toJsonStorage(value.storage),
                access: toJsonAccess(value.access),
                element: toJsonLocalNodeId(value.element),
                shape: value.shape.map((item0) => toJsonTensorDimension(item0)),
                format: toJsonTensorFormat(value.format),
                sharding: toJsonTensorSharding(value.sharding),
                nullability: toJsonNullability(value.nullability),
            };
        case "tensorView":
            return {
                kind: "tensorView",
                kindValue: toJsonReferenceKind(value.kindValue),
                lifetime: toJsonLifetime(value.lifetime),
                storage: toJsonStorage(value.storage),
                access: toJsonAccess(value.access),
                element: toJsonLocalNodeId(value.element),
                shape: value.shape.map((item0) => toJsonTensorDimension(item0)),
                format: toJsonTensorViewFormat(value.format),
                sharding: toJsonTensorSharding(value.sharding),
                nullability: toJsonNullability(value.nullability),
            };
        case "functionSignature":
            return {
                kind: "functionSignature",
                lifetimes: value.lifetimes.map((item0) => toJsonLifetimeParameter(item0)),
                parameters: value.parameters.map((item0) => toJsonSignatureParameter(item0)),
                result: toJsonLocalNodeId(value.result),
            };
        case "function":
            return {
                kind: "function",
                signature: toJsonLocalNodeId(value.signature),
                multiplicity: toJsonMultiplicity(value.multiplicity),
                kindValue: toJsonReferenceKind(value.kindValue),
                lifetime: toJsonLifetime(value.lifetime),
                storage: toJsonStorage(value.storage),
                access: toJsonAccess(value.access),
                nullability: toJsonNullability(value.nullability),
            };
        case "functionPointer":
            return {
                kind: "functionPointer",
                signature: toJsonLocalNodeId(value.signature),
            };
        case "application":
            return {
                kind: "application",
                base: toJsonLocalNodeId(value.base),
                lifetimes: value.lifetimes.map((item0) => toJsonLifetime(item0)),
            };
    }

    throw new SerdeError("unknown enum variant");
}

/** Return one Type from one JSON value. */
export function fromJsonType(value: Json): Type {
    const object = jsonObject(value);
    const kind = jsonString(jsonField(object, "kind"));

    switch (kind) {
        case "error":
            return {
                kind,
            };
        case "never":
            return {
                kind,
            };
        case "void":
            return {
                kind,
            };
        case "boolean":
            return {
                kind,
            };
        case "character":
            return {
                kind,
            };
        case "int":
            return {
                kind,
                width: jsonInteger(jsonField(object, "width")),
                isSigned: jsonBool(jsonField(object, "isSigned")),
            };
        case "isize":
            return {
                kind,
            };
        case "usize":
            return {
                kind,
            };
        case "float":
            return {
                kind,
                float: fromJsonFloatType(jsonField(object, "float")),
            };
        case "typeDescriptor":
            return {
                kind,
            };
        case "typeId":
            return {
                kind,
            };
        case "atomic":
            return {
                kind,
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "dynamic":
            return {
                kind,
                kindValue: fromJsonReferenceKind(jsonField(object, "kindValue")),
                lifetime: fromJsonLifetime(jsonField(object, "lifetime")),
                constraint: fromJsonLocalNodeId(jsonField(object, "constraint")),
                storage: fromJsonStorage(jsonField(object, "storage")),
                access: fromJsonAccess(jsonField(object, "access")),
                nullability: fromJsonNullability(jsonField(object, "nullability")),
            };
        case "reference":
            return {
                kind,
                kindValue: fromJsonReferenceKind(jsonField(object, "kindValue")),
                lifetime: fromJsonLifetime(jsonField(object, "lifetime")),
                storage: fromJsonStorage(jsonField(object, "storage")),
                access: fromJsonAccess(jsonField(object, "access")),
                pointee: fromJsonLocalNodeId(jsonField(object, "pointee")),
                nullability: fromJsonNullability(jsonField(object, "nullability")),
            };
        case "pointer":
            return {
                kind,
                pointee: fromJsonLocalNodeId(jsonField(object, "pointee")),
                access: fromJsonAccess(jsonField(object, "access")),
                nullability: fromJsonNullability(jsonField(object, "nullability")),
            };
        case "slice":
            return {
                kind,
                kindValue: fromJsonReferenceKind(jsonField(object, "kindValue")),
                lifetime: fromJsonLifetime(jsonField(object, "lifetime")),
                element: fromJsonLocalNodeId(jsonField(object, "element")),
                storage: fromJsonStorage(jsonField(object, "storage")),
                access: fromJsonAccess(jsonField(object, "access")),
                nullability: fromJsonNullability(jsonField(object, "nullability")),
            };
        case "uninit":
            return {
                kind,
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "manuallyDrop":
            return {
                kind,
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "fixedArray":
            return {
                kind,
                element: fromJsonLocalNodeId(jsonField(object, "element")),
                length: jsonBigint(jsonField(object, "length")),
                copy: fromJsonCopy(jsonField(object, "copy")),
            };
        case "tuple":
            return {
                kind,
                elements: jsonArray(jsonField(object, "elements")).map((item0) => fromJsonLocalNodeId(item0)),
                copy: fromJsonCopy(jsonField(object, "copy")),
            };
        case "struct":
            return {
                kind,
                fields: jsonArray(jsonField(object, "fields")).map((item0) => fromJsonLocalNodeId(item0)),
                copy: fromJsonCopy(jsonField(object, "copy")),
            };
        case "newtype":
            return {
                kind,
                inner: fromJsonLocalNodeId(jsonField(object, "inner")),
                copy: fromJsonCopy(jsonField(object, "copy")),
            };
        case "variant":
            return {
                kind,
                discriminant: fromJsonLocalNodeId(jsonField(object, "discriminant")),
                cases: jsonArray(jsonField(object, "cases")).map((item0) => fromJsonVariantCase(item0)),
                copy: fromJsonCopy(jsonField(object, "copy")),
            };
        case "vector":
            return {
                kind,
                element: fromJsonLocalNodeId(jsonField(object, "element")),
                lanes: jsonInteger(jsonField(object, "lanes")),
                copy: fromJsonCopy(jsonField(object, "copy")),
            };
        case "tensor":
            return {
                kind,
                kindValue: fromJsonReferenceKind(jsonField(object, "kindValue")),
                lifetime: fromJsonLifetime(jsonField(object, "lifetime")),
                storage: fromJsonStorage(jsonField(object, "storage")),
                access: fromJsonAccess(jsonField(object, "access")),
                element: fromJsonLocalNodeId(jsonField(object, "element")),
                shape: jsonArray(jsonField(object, "shape")).map((item0) => fromJsonTensorDimension(item0)),
                format: fromJsonTensorFormat(jsonField(object, "format")),
                sharding: fromJsonTensorSharding(jsonField(object, "sharding")),
                nullability: fromJsonNullability(jsonField(object, "nullability")),
            };
        case "tensorView":
            return {
                kind,
                kindValue: fromJsonReferenceKind(jsonField(object, "kindValue")),
                lifetime: fromJsonLifetime(jsonField(object, "lifetime")),
                storage: fromJsonStorage(jsonField(object, "storage")),
                access: fromJsonAccess(jsonField(object, "access")),
                element: fromJsonLocalNodeId(jsonField(object, "element")),
                shape: jsonArray(jsonField(object, "shape")).map((item0) => fromJsonTensorDimension(item0)),
                format: fromJsonTensorViewFormat(jsonField(object, "format")),
                sharding: fromJsonTensorSharding(jsonField(object, "sharding")),
                nullability: fromJsonNullability(jsonField(object, "nullability")),
            };
        case "functionSignature":
            return {
                kind,
                lifetimes: jsonArray(jsonField(object, "lifetimes")).map((item0) => fromJsonLifetimeParameter(item0)),
                parameters: jsonArray(jsonField(object, "parameters")).map((item0) => fromJsonSignatureParameter(item0)),
                result: fromJsonLocalNodeId(jsonField(object, "result")),
            };
        case "function":
            return {
                kind,
                signature: fromJsonLocalNodeId(jsonField(object, "signature")),
                multiplicity: fromJsonMultiplicity(jsonField(object, "multiplicity")),
                kindValue: fromJsonReferenceKind(jsonField(object, "kindValue")),
                lifetime: fromJsonLifetime(jsonField(object, "lifetime")),
                storage: fromJsonStorage(jsonField(object, "storage")),
                access: fromJsonAccess(jsonField(object, "access")),
                nullability: fromJsonNullability(jsonField(object, "nullability")),
            };
        case "functionPointer":
            return {
                kind,
                signature: fromJsonLocalNodeId(jsonField(object, "signature")),
            };
        case "application":
            return {
                kind,
                base: fromJsonLocalNodeId(jsonField(object, "base")),
                lifetimes: jsonArray(jsonField(object, "lifetimes")).map((item0) => fromJsonLifetime(item0)),
            };
    }

    throw new SerdeError(`unknown enum variant: ${kind}`);
}

/** A named type declaration in MIR text format. */
export type TypeDeclaration = {
    /** The declaration name. */
    readonly name: StringId;
    /** Concrete generic arguments specializing this type. */
    readonly arguments: ReadonlyArray<StaticId>;
    /** Lifetime parameters in type-local slot order. */
    readonly lifetimes: ReadonlyArray<LifetimeParameter>;
    /** The identified type. */
    readonly ty: LocalNodeId;
};

export const TypeDeclaration = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: TypeDeclaration): void {
        encodeTypeDeclaration(writer, value);
    },

    /** Decode one TypeDeclaration. */
    decode(reader: BinaryReader): TypeDeclaration {
        return decodeTypeDeclaration(reader);
    },

    /** Return this value as JSON. */
    toJson(value: TypeDeclaration): Json {
        return toJsonTypeDeclaration(value);
    },

    /** Return one TypeDeclaration from one JSON value. */
    fromJson(value: Json): TypeDeclaration {
        return fromJsonTypeDeclaration(value);
    },
};

/** Encode one TypeDeclaration. */
export function encodeTypeDeclaration(writer: BinaryWriter, value: TypeDeclaration): void {
    encodeStringId(writer, value.name);
    writer.writeUnsigned(value.arguments.length);
    for (const item1 of value.arguments) {
        encodeStaticId(writer, item1);
    }
    writer.writeUnsigned(value.lifetimes.length);
    for (const item2 of value.lifetimes) {
        encodeLifetimeParameter(writer, item2);
    }
    encodeLocalNodeId(writer, value.ty);
}

/** Decode one TypeDeclaration. */
export function decodeTypeDeclaration(reader: BinaryReader): TypeDeclaration {
    const name = decodeStringId(reader);
    const arguments_ = (() => { const length1 = reader.readNumber(); const items1: Array<StaticId> = []; for (let index = 0; index < length1; index += 1) { items1.push(decodeStaticId(reader)); } return items1; })();
    const lifetimes = (() => { const length2 = reader.readNumber(); const items2: Array<LifetimeParameter> = []; for (let index = 0; index < length2; index += 1) { items2.push(decodeLifetimeParameter(reader)); } return items2; })();
    const ty = decodeLocalNodeId(reader);

    return {
        name,
        arguments: arguments_,
        lifetimes,
        ty,
    };
}

/** Return one JSON value for one TypeDeclaration. */
export function toJsonTypeDeclaration(value: TypeDeclaration): Json {
    return {
        name: toJsonStringId(value.name),
        arguments: value.arguments.map((item0) => toJsonStaticId(item0)),
        lifetimes: value.lifetimes.map((item0) => toJsonLifetimeParameter(item0)),
        ty: toJsonLocalNodeId(value.ty),
    };
}

/** Return one TypeDeclaration from one JSON value. */
export function fromJsonTypeDeclaration(value: Json): TypeDeclaration {
    const object = jsonObject(value);

    return {
        name: fromJsonStringId(jsonField(object, "name")),
        arguments: jsonArray(jsonField(object, "arguments")).map((item0) => fromJsonStaticId(item0)),
        lifetimes: jsonArray(jsonField(object, "lifetimes")).map((item0) => fromJsonLifetimeParameter(item0)),
        ty: fromJsonLocalNodeId(jsonField(object, "ty")),
    };
}

/** Stable canonical fingerprint of one MIR type. */
export type TypeFingerprint = bigint;

export const TypeFingerprint = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: TypeFingerprint): void {
        encodeTypeFingerprint(writer, value);
    },

    /** Decode one TypeFingerprint. */
    decode(reader: BinaryReader): TypeFingerprint {
        return decodeTypeFingerprint(reader);
    },

    /** Return this value as JSON. */
    toJson(value: TypeFingerprint): Json {
        return toJsonTypeFingerprint(value);
    },

    /** Return one TypeFingerprint from one JSON value. */
    fromJson(value: Json): TypeFingerprint {
        return fromJsonTypeFingerprint(value);
    },
};

/** Encode one TypeFingerprint. */
export function encodeTypeFingerprint(writer: BinaryWriter, value: TypeFingerprint): void {
    writer.writeUnsigned(value);
}

/** Decode one TypeFingerprint. */
export function decodeTypeFingerprint(reader: BinaryReader): TypeFingerprint {
    return reader.readUnsigned();
}

/** Return one JSON value for one TypeFingerprint. */
export function toJsonTypeFingerprint(value: TypeFingerprint): Json {
    return value.toString();
}

/** Return one TypeFingerprint from one JSON value. */
export function fromJsonTypeFingerprint(value: Json): TypeFingerprint {
    return jsonBigint(value);
}

/** One sum case. */
export type VariantCase = {
    /** The discriminant constant selecting this case. */
    readonly discriminant: Constant;
    /** The logical payload type. */
    readonly ty: LocalNodeId;
};

export const VariantCase = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: VariantCase): void {
        encodeVariantCase(writer, value);
    },

    /** Decode one VariantCase. */
    decode(reader: BinaryReader): VariantCase {
        return decodeVariantCase(reader);
    },

    /** Return this value as JSON. */
    toJson(value: VariantCase): Json {
        return toJsonVariantCase(value);
    },

    /** Return one VariantCase from one JSON value. */
    fromJson(value: Json): VariantCase {
        return fromJsonVariantCase(value);
    },
};

/** Encode one VariantCase. */
export function encodeVariantCase(writer: BinaryWriter, value: VariantCase): void {
    encodeConstant(writer, value.discriminant);
    encodeLocalNodeId(writer, value.ty);
}

/** Decode one VariantCase. */
export function decodeVariantCase(reader: BinaryReader): VariantCase {
    const discriminant = decodeConstant(reader);
    const ty = decodeLocalNodeId(reader);

    return {
        discriminant,
        ty,
    };
}

/** Return one JSON value for one VariantCase. */
export function toJsonVariantCase(value: VariantCase): Json {
    return {
        discriminant: toJsonConstant(value.discriminant),
        ty: toJsonLocalNodeId(value.ty),
    };
}

/** Return one VariantCase from one JSON value. */
export function fromJsonVariantCase(value: Json): VariantCase {
    const object = jsonObject(value);

    return {
        discriminant: fromJsonConstant(jsonField(object, "discriminant")),
        ty: fromJsonLocalNodeId(jsonField(object, "ty")),
    };
}
